scriptsCode.onCellValueChanged:
// (业务表格)AGGrid1.onCellValueChanged
debugger;
        const rowSetArray = MDModel5.getMdmDataModel().getDataSet("HLZB_htmxb").getRowSetArray();
        
        // 遍历所有行，批量更新字段
        rowSetArray.forEach(row => {
            // 获取当前行的cpprice值（使用变化后的值）
            const cp = row.getValue("cpprice", null);
            
            // 1. 计算并更新预付款cpyfk
            const a = FormNumberInput6.getValue();
            const a1 = a / 100;
            const cpp1 = cp * a1;
            row.putString("cpyfk", cpp1);
            
            // 2. 计算并更新到货款daohk
            const b = FormNumberInput7.getValue("daohkbl");
            const b1 = b / 100;
            const cpp2 = cp * b1;
            row.putString("daohk", cpp2);
            
            // 3. 计算并更新发货款fahk
            const c = FormNumberInput5.getValue("fahkbl");
            const c1 = c / 100;
            const cpp3 = cp * c1;
            row.putString("fahk", cpp3);
            
            // 4. 计算并更新进度款jduk
            const d = FormNumberInput8.getValue("jindkbl");
            const d1 = d / 100;
            const cpp4 = cp * d1;
            row.putString("jduk", cpp4);
            
            // 5. 计算并更新验收款yansk
            const e = FormNumberInput9.getValue("yanskbl");
            const e1 = e / 100;
            const cpp5 = cp * e1;
            row.putString("yansk", cpp5);
            
            // 6. 计算并更新质保金zbaoj
            const f = FormNumberInput10.getValue("zhibjbl");
            const f1 = f / 100;
            const cpp6 = cp * f1;
            row.putString("zbaoj", cpp6);
        });
    // }

